er when its request is approved rather than being handed the raw grace period here.","type":"object","additionalProperties":false,"required":["eventId","startDate","endDate","groupFloor","tiers"],"properties":{"eventId":{"type":"string","minLength":1},"startDate":{"type":"string","format":"date"},"endDate":{"type":"string","format":"date"},"groupFloor":{"type":"integer","minimum":1},"tiers":{"type":"array","items":{"\$ref":"#/\$defs/Tier"}}}},"Tier":{"title":"Tier","type":"object","additionalProperties":false,"required":["name","dripPerTick"],"properties":{"name":{"type":"string","minLength":1,"description":"How the menu names it: desk, busy-desk."},"dripPerTick":{"type":"integer","minimum":1,"description":"How many tokens a tick under this tier yields."}}},"TickLength":{"title":"TickLength","type":"string","pattern":"^P(?:\\\\d+D(?:T\\\\d+H)?|T\\\\d+H)\$","description":"The length of one tick of the drip, as an ISO 8601 duration in days and/or hours — at least `PT1H`. A label\'s tick `t` is the window starting `t` tick lengths after the label\'s start (`vtc/vetting/vetters/pcs-tokens`)."}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: false,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
